content:
:root {
  --bg-primary: #0f172a;
  --bg-secondary: #1e293b;
  --bg-tertiary: #334155;
  --text-main: #f8fafc;
  --text-muted: #94a3b8;
  --accent-cyan: #06b6d4;
  --accent-cyan-hover: #0891b2;
  --accent-blue: #3b82f6;
  --accent-blue-hover: #2563eb;
  --accent-red: #ef4444;
  --accent-red-hover: #dc2626;
  --accent-emerald: #10b981;
  --border-color: #334155;
  --border-focus: #38bdf8;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.3);
  --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.4);
  --shadow-lg: 0 10px 25px -5px rgba(0, 0, 0, 0.5);
  --font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
}

body {
  background-color: var(--bg-primary);
  color: var(--text-main);
  font-family: var(--font-family);
  min-height: 100vh;
  line-height: 1.5;
  overflow-x: hidden;
  user-select: none;
}

/* アプリ全体コンテナ */
.sim-container {
  display: flex;
  flex-direction: column;
  min-height: 100vh;
  max-width: 1400px;
  margin: 0 auto;
  padding: 16px 20px 24px;
  gap: 16px;
}

/* ヘッダーエリア */
.sim-header {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.sim-title {
  font-size: 1.75rem;
  font-weight: 800;
  letter-spacing: -0.025em;
  background: linear-gradient(135deg, #38bdf8 0%, #818cf8 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  display: flex;
  align-items: center;
  gap: 8px;
}

.sim-subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
}

.help-text {
  font-size: 0.85rem;
  color: #38bdf8;
  background-color: rgba(56, 189, 248, 0.1);
  border: 1px solid rgba(56, 189, 248, 0.25);
  padding: 6px 12px;
  border-radius: var(--radius-sm);
  display: inline-flex;
  align-items: center;
  gap: 6px;
  width: fit-content;
  margin-top: 4px;
}

/* メインレイアウト: キャンバス + 操作パネル */
.main-layout {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 20px;
  flex: 1;
  min-height: 0;
}

@media (max-width: 960px) {
  .main-layout {
    grid-template-columns: 1fr;
  }
}

/* キャンバス領域 */
.canvas-wrapper {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 480px;
  background: radial-gradient(circle at 50% 20%, #1e293b 0%, #0b1120 100%);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-lg);
  cursor: crosshair;
  touch-action: none;
  display: flex;
}

.sim-canvas {
  width: 100%;
  height: 100%;
  display: block;
}

/* 統計バッジ */
.stats-container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 8px 12px;
  background-color: rgba(15, 23, 42, 0.6);
  border-radius: var(--radius-md);
  border: 1px solid var(--border-color);
}

.stats-badge {
  font-size: 0.85rem;
  font-weight: 600;
  color: #cbd5e1;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.stats-badge strong {
  font-size: 1.1rem;
  color: #38bdf8;
  font-family: monospace;
}

/* コントロールパネル */
.sim-controls {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.controls-panel {
  background-color: var(--bg-secondary);
  border: 1px solid var(--border-color);
  border-radius: var(--radius-lg);
  padding: 20px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  box-shadow: var(--shadow-md);
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.control-label {
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 0.875rem;
  font-weight: 600;
  color: #cbd5e1;
}

.slider-container {
  display: flex;
  align-items: center;
  gap: 12px;
}

.slider-input {
  flex: 1;
  -webkit-appearance: none;
  appearance: none;
  height: 6px;
  background: var(--bg-tertiary);
  border-radius: 9999px;
  outline: none;
  cursor: pointer;
  transition: background 0.2s ease;
}

.slider-input:hover {
  background: #475569;
}

.slider-input:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

.slider-input::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: #38bdf8;
  box-shadow: 0 0 8px rgba(56, 189, 248, 0.6);
  cursor: pointer;
  border: 2px solid #ffffff;
  transition: transform 0.15s ease, background-color 0.15s ease;
}

.slider-input::-webkit-slider-thumb:hover {
  transform: scale(1.15);
  background: #0ea5e9;
}

.slider-input::-webkit-slider-thumb:active {
  transform: scale(0.95);
}

.slider-input::-moz-range-thumb {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: #38bdf8;
  box-shadow: 0 0 8px rgba(56, 189, 248, 0.6);
  cursor: pointer;
  border: 2px solid #ffffff;
  transition: transform 0.15s ease, background-color 0.15s ease;
}

.slider-value {
  font-family: monospace;
  font-size: 0.85rem;
  color: #38bdf8;
  min-width: 44px;
  text-align: right;
  font-weight: 700;
  background-color: var(--bg-primary);
  padding: 2px 6px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-color);
}

/* ボタン群 */
.btn-group {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.sim-btn {
  flex: 1;
  min-width: 100px;
  padding: 10px 14px;
  font-size: 0.875rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius-md);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: var(--shadow-sm);
  outline: none;
}

.sim-btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

.sim-btn:active {
  transform: translateY(1px);
}

.sim-btn-primary {
  background: linear-gradient(135deg, #0284c7 0%, #2563eb 100%);
  color: #ffffff;
}

.sim-btn-primary:hover {
  background: linear-gradient(135deg, #0369a1 0%, #1d4ed8 100%);
  box-shadow: 0 4px 12px rgba(37, 99, 235, 0.4);
}

.sim-btn-secondary {
  background-color: var(--bg-tertiary);
  color: #f1f5f9;
  border: 1px solid #475569;
}

.sim-btn-secondary:hover {
  background-color: #475569;
  color: #ffffff;
}

.sim-btn-danger {
  background: linear-gradient(135deg, #dc2626 0%, #b91c1c 100%);
  color: #ffffff;
}

.sim-btn-danger:hover {
  background: linear-gradient(135deg, #b91c1c 0%, #991b1b 100%);
  box-shadow: 0 4px 12px rgba(220, 38, 38, 0.4);
}

@media (max-width: 640px) {
  .sim-container {
    padding: 12px;
    gap: 12px;
  }

  .canvas-wrapper {
    min-height: 380px;
  }

  .controls-panel {
    padding: 16px;
    gap: 16px;
  }

  .btn-group {
    flex-direction: column;
  }

  .sim-btn {
    width: 100%;
    min-height: 42px;
  }
}

export interface BallItem {
  id: number;
  x: number;
  y: number;
  vx: number;
  vy: number;
  radius: number;
  color: string;
  bounce: number;
}

export interface PhysicsParams {
  gravity: number;
  bounce: number;
  airResistance: number;
  ballSize: number;
}

export interface PhysicsCanvasProps {
  params: PhysicsParams;
  balls: BallItem[];
  onAddBall: (x: number, y: number) => void;
}

export interface ControlsProps {
  params: PhysicsParams;
  onParamsChange: (newParams: PhysicsParams) => void;
  onAddRandomBalls: (count: number) => void;
  onClearBalls: () => void;
  ballCount: number;
}

import { useRef, useEffect, useCallback } from 'react';
import { BallItem, PhysicsCanvasProps } from '../types';

const PhysicsCanvas = ({ params, balls = [], onAddBall }: PhysicsCanvasProps) => {
  const canvasRef = useRef<HTMLCanvasElement | null>(null);
  const containerRef = useRef<HTMLDivElement | null>(null);
  const ballsRef = useRef<BallItem[]>(balls);
  const paramsRef = useRef(params);
  const isPointerDownRef = useRef(false);
  const lastAddPosRef = useRef<{ x: number; y: number } | null>(null);

  // 最新の props を ref に同期
  useEffect(() => {
    ballsRef.current = balls;
  }, [balls]);

  useEffect(() => {
    paramsRef.current = params;
  }, [params]);

  // Canvas 解像度のリサイズハンドリング
  const updateCanvasSize = useCallback(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;

    const rect = container.getBoundingClientRect();
    const dpr = window.devicePixelRatio || 1;
    canvas.width = Math.floor(rect.width * dpr);
    canvas.height = Math.floor(rect.height * dpr);
  }, []);

  useEffect(() => {
    updateCanvasSize();
    window.addEventListener('resize', updateCanvasSize);
    return () => {
      window.removeEventListener('resize', updateCanvasSize);
    };
  }, [updateCanvasSize]);

  // 物理演算ループ & Canvas 描画
  useEffect(() => {
    let animationFrameId: number;

    const loop = () => {
      const canvas = canvasRef.current;
      if (!canvas) return;

      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      const dpr = window.devicePixelRatio || 1;
      const width = canvas.width / dpr;
      const height = canvas.height / dpr;

      ctx.save();
      ctx.scale(dpr, dpr);
      ctx.clearRect(0, 0, width, height);

      const currentParams = paramsRef.current;
      const currentBalls = ballsRef.current;
      const gravity = currentParams.gravity;
      const globalBounce = currentParams.bounce;
      const airResistance = 1 - currentParams.airResistance;

      // 物理演算（位置・速度の更新）
      for (let i = 0; i < currentBalls.length; i++) {
        const b = currentBalls[i];

        // 重力加算
        b.vy += gravity;

        // 空気抵抗
        b.vx *= airResistance;
        b.vy *= airResistance;

        // 座標更新
        b.x += b.vx;
        b.y += b.vy;

        const effectiveBounce = (b.bounce + globalBounce) / 2;

        // 床との衝突判定
        if (b.y + b.radius > height) {
          b.y = height - b.radius;
          b.vy = -b.vy * effectiveBounce;
          // 微小なバウンドの静止化
          if (Math.abs(b.vy) < 0.2 && gravity > 0) {
            b.vy = 0;
          }
          // 床の摩擦
          b.vx *= 0.98;
        }

        // 天井との衝突判定
        if (b.y - b.radius < 0) {
          b.y = b.radius;
          b.vy = -b.vy * effectiveBounce;
        }

        // 左壁との衝突判定
        if (b.x - b.radius < 0) {
          b.x = b.radius;
          b.vx = -b.vx * effectiveBounce;
        }

        // 右壁との衝突判定
        if (b.x + b.radius > width) {
          b.x = width - b.radius;
          b.vx = -b.vx * effectiveBounce;
        }
      }

      // ボール同士の衝突判定と反射処理
      for (let i = 0; i < currentBalls.length; i++) {
        for (let j = i + 1; j < currentBalls.length; j++) {
          const b1 = currentBalls[i];
          const b2 = currentBalls[j];

          const dx = b2.x - b1.x;
          const dy = b2.y - b1.y;
          const dist = Math.sqrt(dx * dx + dy * dy);
          const minDist = b1.radius + b2.radius;

          if (dist < minDist && dist > 0) {
            // 重なり解消
            const overlap = (minDist - dist) / 2;
            const nx = dx / dist;
            const ny = dy / dist;

            b1.x -= nx * overlap;
            b1.y -= ny * overlap;
            b2.x += nx * overlap;
            b2.y += ny * overlap;

            // 相対速度
            const kx = b1.vx - b2.vx;
            const ky = b1.vy - b2.vy;
            const p = 2 * (nx * kx + ny * ky) / 2; // 質量が等しいと仮定した弾性衝突

            const avgBounce = (b1.bounce + b2.bounce + globalBounce) / 3;

            b1.vx -= p * nx * avgBounce;
            b1.vy -= p * ny * avgBounce;
            b2.vx += p * nx * avgBounce;
            b2.vy += p * ny * avgBounce;
          }
        }
      }

      // 描画処理
      for (let i = 0; i < currentBalls.length; i++) {
        const b = currentBalls[i];

        // ボールの接地影を描画
        const shadowY = Math.min(height - 2, b.y + b.radius + 6);
        const distanceToGround = height - (b.y + b.radius);
        const shadowScale = Math.max(0.2, 1 - distanceToGround / 250);
        const shadowAlpha = Math.max(0.05, 0.45 * (1 - distanceToGround / 250));

        if (shadowAlpha > 0.05) {
          ctx.beginPath();
          ctx.ellipse(
            b.x,
            shadowY,
            b.radius * shadowScale,
            b.radius * 0.25 * shadowScale,
            0,
            0,
            Math.PI * 2
          );
          ctx.fillStyle = `rgba(0, 0, 0, ${shadowAlpha.toFixed(2)})`;
          ctx.fill();
        }

        // ボール本体（グラデーションで立体感を持たせる）
        ctx.beginPath();
        ctx.arc(b.x, b.y, b.radius, 0, Math.PI * 2);

        const highlightX = b.x - b.radius * 0.35;
        const highlightY = b.y - b.radius * 0.35;
        const gradient = ctx.createRadialGradient(
          highlightX,
          highlightY,
          b.radius * 0.1,
          b.x,
          b.y,
          b.radius
        );

        gradient.addColorStop(0, '#ffffff');
        gradient.addColorStop(0.3, b.color);
        gradient.addColorStop(1, '#050a14');

        ctx.fillStyle = gradient;
        ctx.fill();

        // 輪郭線
        ctx.lineWidth = 1.5;
        ctx.strokeStyle = 'rgba(255, 255, 255, 0.3)';
        ctx.stroke();
      }

      ctx.restore();
      animationFrameId = requestAnimationFrame(loop);
    };

    animationFrameId = requestAnimationFrame(loop);
    return () => {
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  // ポインター操作（クリック＆ドラッグで連続生成）
  const getCoordinates = (e: React.PointerEvent<HTMLCanvasElement>) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();
    return {
      x: e.clientX - rect.left,
      y: e.clientY - rect.top,
    };
  };

  const handlePointerDown = (e: React.PointerEvent<HTMLCanvasElement>) => {
    e.currentTarget.setPointerCapture(e.pointerId);
    isPointerDownRef.current = true;
    const { x, y } = getCoordinates(e);
    lastAddPosRef.current = { x, y };
    onAddBall?.(x, y);
  };

  const handlePointerMove = (e: React.PointerEvent<HTMLCanvasElement>) => {
    if (!isPointerDownRef.current) return;
    const { x, y } = getCoordinates(e);

    // 一定距離以上移動した場合に新しいボールを追加
    if (lastAddPosRef.current) {
      const dx = x - lastAddPosRef.current.x;
      const dy = y - lastAddPosRef.current.y;
      const dist = Math.sqrt(dx * dx + dy * dy);
      if (dist > 35) {
        lastAddPosRef.current = { x, y };
        onAddBall?.(x, y);
      }
    }
  };

  const handlePointerUp = (e: React.PointerEvent<HTMLCanvasElement>) => {
    if (e.currentTarget.hasPointerCapture(e.pointerId)) {
      e.currentTarget.releasePointerCapture(e.pointerId);
    }
    isPointerDownRef.current = false;
    lastAddPosRef.current = null;
  };

  return (
    <div className="canvas-wrapper" ref={containerRef}>
      <canvas
        ref={canvasRef}
        className="sim-canvas"
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerCancel={handlePointerUp}
      />
    </div>
  );
};

export default PhysicsCanvas;

import { ControlsProps } from '../types';
import { RotateCcw, Plus, Trash2, Sliders, Activity } from 'lucide-react';

const Controls = ({
  params,
  onParamsChange,
  onAddRandomBalls,
  onClearBalls,
  ballCount = 0,
}: ControlsProps) => {
  const handleGravityChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onParamsChange({ ...params, gravity: parseFloat(e.target.value) });
  };

  const handleBounceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onParamsChange({ ...params, bounce: parseFloat(e.target.value) });
  };

  const handleAirResistanceChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onParamsChange({ ...params, airResistance: parseFloat(e.target.value) });
  };

  const handleBallSizeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    onParamsChange({ ...params, ballSize: parseInt(e.target.value, 10) });
  };

  const handleResetParams = () => {
    onParamsChange({
      gravity: 0.5,
      bounce: 0.75,
      airResistance: 0.005,
      ballSize: 18,
    });
  };

  return (
    <div className="sim-controls">
      {/* 統計バッジ */}
      <div className="stats-container">
        <span className="stats-badge">
          <Activity size={18} color="#38bdf8" />
          現在のボール数: <strong>{ballCount}</strong> 個
        </span>
        <button
          type="button"
          className="sim-btn sim-btn-secondary"
          onClick={handleResetParams}
          title="物理定数を初期値に戻す"
          style={{ padding: '4px 8px', fontSize: '0.75rem', minWidth: 'auto' }}
        >
          <RotateCcw size={14} />
          定数リセット
        </button>
      </div>

      {/* パラメータ設定パネル */}
      <div className="controls-panel">
        {/* 重力の強さ */}
        <div className="control-group">
          <div className="control-label">
            <span>重力の強さ (Gravity)</span>
            <span className="slider-value">{params.gravity.toFixed(2)}</span>
          </div>
          <div className="slider-container">
            <input
              type="range"
              className="slider-input"
              min="0"
              max="1.5"
              step="0.05"
              value={params.gravity}
              onChange={handleGravityChange}
              aria-label="重力の強さ"
            />
          </div>
        </div>

        {/* 反発係数 */}
        <div className="control-group">
          <div className="control-label">
            <span>反発係数 (Bounce / e)</span>
            <span className="slider-value">{params.bounce.toFixed(2)}</span>
          </div>
          <div className="slider-container">
            <input
              type="range"
              className="slider-input"
              min="0.1"
              max="1.0"
              step="0.05"
              value={params.bounce}
              onChange={handleBounceChange}
              aria-label="反発係数"
            />
          </div>
        </div>

        {/* 空気抵抗 */}
        <div className="control-group">
          <div className="control-label">
            <span>空気抵抗 (Air Drag)</span>
            <span className="slider-value">{params.airResistance.toFixed(3)}</span>
          </div>
          <div className="slider-container">
            <input
              type="range"
              className="slider-input"
              min="0"
              max="0.05"
              step="0.002"
              value={params.airResistance}
              onChange={handleAirResistanceChange}
              aria-label="空気抵抗"
            />
          </div>
        </div>

        {/* 生成ボールのサイズ */}
        <div className="control-group">
          <div className="control-label">
            <span>ボールの大きさ (Radius)</span>
            <span className="slider-value">{params.ballSize}px</span>
          </div>
          <div className="slider-container">
            <input
              type="range"
              className="slider-input"
              min="8"
              max="40"
              step="2"
              value={params.ballSize}
              onChange={handleBallSizeChange}
              aria-label="ボールの大きさ"
            />
          </div>
        </div>

        {/* 一括操作ボタン群 */}
        <div className="btn-group">
          <button
            type="button"
            className="sim-btn sim-btn-primary"
            onClick={() => onAddRandomBalls(5)}
          >
            <Plus size={16} />
            +5個 追加
          </button>
          <button
            type="button"
            className="sim-btn sim-btn-primary"
            onClick={() => onAddRandomBalls(20)}
          >
            <Plus size={16} />
            +20個 追加
          </button>
        </div>

        <div className="btn-group">
          <button
            type="button"
            className="sim-btn sim-btn-danger"
            onClick={onClearBalls}
          >
            <Trash2 size={16} />
            ボールを全消去
          </button>
        </div>
      </div>
    </div>
  );
};

export default Controls;

import { useState, useCallback } from 'react';
import PhysicsCanvas from './components/PhysicsCanvas';
import Controls from './components/Controls';
import { BallItem, PhysicsParams } from './types';
import { CircleDot, Sparkles, MousePointerClick } from 'lucide-react';
import './index.css';

// 鮮やかでコントラストの高いカラーパレット
const BALL_COLORS = [
  '#38bdf8', // スカイブルー
  '#f43f5e', // ローズ
  '#10b981', // エメラルド
  '#a855f7', // パープル
  '#f59e0b', // アンバー
  '#ec4899', // ピンク
  '#06b6d4', // シアン
  '#84cc16', // ライム
];

let nextBallId = 1;

// 初期ボール群を生成
const createInitialBalls = (): BallItem[] => {
  const initial: BallItem[] = [];
  const count = 8;
  for (let i = 0; i < count; i++) {
    const radius = 16 + Math.floor(Math.random() * 8);
    initial.push({
      id: nextBallId++,
      x: 80 + i * 55 + (Math.random() * 20 - 10),
      y: 60 + (i % 3) * 40,
      vx: (Math.random() - 0.5) * 6,
      vy: (Math.random() - 0.2) * 3,
      radius,
      color: BALL_COLORS[i % BALL_COLORS.length],
      bounce: 0.7 + Math.random() * 0.15,
    });
  }
  return initial;
};

const App = () => {
  const [params, setParams] = useState<PhysicsParams>({
    gravity: 0.5,
    bounce: 0.75,
    airResistance: 0.005,
    ballSize: 18,
  });

  const [balls, setBalls] = useState<BallItem[]>(() => createInitialBalls());

  // キャンバスクリック/タップによる単一ボール追加
  const handleAddBall = useCallback((x: number, y: number) => {
    setBalls((prev) => {
      // 最大ボール数制限（パフォーマンス保護）
      if (prev.length >= 250) {
        return prev;
      }
      const randomColor = BALL_COLORS[Math.floor(Math.random() * BALL_COLORS.length)];
      const newBall: BallItem = {
        id: nextBallId++,
        x,
        y,
        vx: (Math.random() - 0.5) * 6,
        vy: (Math.random() - 0.5) * 4,
        radius: params.ballSize,
        color: randomColor,
        bounce: params.bounce,
      };
      return [...prev, newBall];
    });
  }, [params.ballSize, params.bounce]);

  // ランダムな位置に複数ボールを一括追加
  const handleAddRandomBalls = useCallback((count: number) => {
    setBalls((prev) => {
      const allowedCount = Math.min(count, Math.max(0, 250 - prev.length));
      if (allowedCount <= 0) return prev;

      const newBalls: BallItem[] = [];
      for (let i = 0; i < allowedCount; i++) {
        const randomColor = BALL_COLORS[Math.floor(Math.random() * BALL_COLORS.length)];
        const sizeOffset = Math.floor(Math.random() * 8) - 4;
        const currentRadius = Math.max(8, params.ballSize + sizeOffset);

        newBalls.push({
          id: nextBallId++,
          x: 60 + Math.random() * 320,
          y: 40 + Math.random() * 120,
          vx: (Math.random() - 0.5) * 8,
          vy: (Math.random() - 0.5) * 4,
          radius: currentRadius,
          color: randomColor,
          bounce: Math.min(0.95, params.bounce + (Math.random() * 0.1 - 0.05)),
        });
      }
      return [...prev, ...newBalls];
    });
  }, [params.ballSize, params.bounce]);

  // 全ボール消去
  const handleClearBalls = useCallback(() => {
    setBalls([]);
  }, []);

  return (
    <div className="sim-container">
      {/* ヘッダーエリア */}
      <header className="sim-header">
        <h1 className="sim-title">
          <CircleDot size={30} color="#38bdf8" />
          物理バウンドシミュレーター
        </h1>
        <p className="sim-subtitle">
          重力加速度と反発係数によるリアルタイム物理シミュレーション
        </p>
        <div className="help-text">
          <MousePointerClick size={16} />
          キャンバス内をクリックまたはドラッグすると、その場所にボールが出現します
        </div>
      </header>

      {/* メインレイアウト */}
      <main className="main-layout">
        {/* キャンバス描画部 */}
        <PhysicsCanvas
          params={params}
          balls={balls}
          onAddBall={handleAddBall}
        />

        {/* 操作パネル部 */}
        <Controls
          params={params}
          onParamsChange={setParams}
          onAddRandomBalls={handleAddRandomBalls}
          onClearBalls={handleClearBalls}
          ballCount={balls.length}
        />
      </main>
    </div>
  );
};

export default App;
